steps.solution:
function firstFiveGuests(guests) {
  const firstFive = []
  for (let i = 0; i < guests.length && i < 5; i++) {
    firstFive.push(guests[i])
  }
  return firstFive
}

console.log(firstFiveGuests(['Ana', 'Ben', 'Cleo']))
